static T Max<T>(T[] w)
    where T : IComparable<T>
{
    T m = w[0];
    foreach (T x in w)
        if (x.CompareTo(m) > 0) m = x;
    return m;
}
Console.WriteLine(Max(new[]
  { "Birne", "Apfel", "Zitrone" }));

static int Zaehle<T>(
    IEnumerable<T> werte,
    Func<T, bool> bed)
{
    int n = 0;
    foreach (var w in werte)
        if (bed(w)) n++;
    return n;
}
Console.WriteLine(Zaehle(
    new[] { "a", "bb", "ccc" },
    w => w.Length >= 2));

